import{_ as d,a8 as a,o as r,c as o,ah as l,K as t}from"./chunks/framework.DX2Vcg1x.js";import"./chunks/theme.BzIrHAwa.js";const w=JSON.parse('{"title":"OpenClaw 学习路径","description":"OpenClaw 学习与掌握核心指南——按重要性分四梯队的学习路径与4周路线图","frontmatter":{"abstract":"OpenClaw 源码学习路径指南，按重要性分层从必须掌握的 Agent 执行引擎、回复管道到插件 SDK 等进阶扩展能力。","type":"guides","tags":["AI","OpenClaw","学习路径","入门"],"domain":"AI","description":"OpenClaw 学习与掌握核心指南——按重要性分四梯队的学习路径与4周路线图","created":"2026-09-07T00:00:00.000Z","updated":"2026-09-07T00:00:00.000Z","status":"integrated","source":"[[Resources/OpenClaw/OpenClaw 学习与掌握核心指南]]","related":["[[🦀 OpenClaw-MOC]]","[[OpenClaw-Agent-Engine]]","[[OpenClaw-Plugin-System]]","[[OpenClaw-架构总览]]"],"category":["🦀 OpenClaw","操作指南"]},"headers":[],"relativePath":"vault/Knowledge/AI/OpenClaw-学习路径.md","filePath":"vault/Knowledge/AI/OpenClaw-学习路径.md","lastUpdated":1790655645000}'),c={name:"vault/Knowledge/AI/OpenClaw-学习路径.md"};function p(i,e,h,g,u,b){const n=a("NolebaseGitContributors"),s=a("NolebaseGitChangelog");return r(),o("div",null,[e[0]||(e[0]=l(`<h1 id="openclaw-学习路径" tabindex="-1">OpenClaw 学习路径 <a class="header-anchor" href="#openclaw-学习路径" aria-label="Permalink to “OpenClaw 学习路径”">​</a></h1><blockquote><p>按重要性分层的核心学习路径，从「必须掌握的核心引擎」到「进阶扩展能力」。</p></blockquote><h2 id="第一梯队-必须掌握的核心引擎" tabindex="-1">第一梯队：必须掌握的核心引擎 <a class="header-anchor" href="#第一梯队-必须掌握的核心引擎" aria-label="Permalink to “第一梯队：必须掌握的核心引擎”">​</a></h2><h3 id="_1-agent-执行引擎-src-agents-embedded-agent-runner" tabindex="-1">1. Agent 执行引擎（<code>src/agents/embedded-agent-runner/</code>） <a class="header-anchor" href="#_1-agent-执行引擎-src-agents-embedded-agent-runner" aria-label="Permalink to “1. Agent 执行引擎（src/agents/embedded-agent-runner/）”">​</a></h3><p>整个 OpenClaw 的心脏。理解它就理解了产品。</p><table tabindex="0"><thead><tr><th>文件</th><th>核心概念</th></tr></thead><tbody><tr><td><code>run.ts</code></td><td><code>while(true)</code> 主循环 — Agent 如何无限循环运行</td></tr><tr><td><code>run/attempt.ts</code></td><td>单次 LLM 尝试 — 发 prompt、处理工具调用、返回结果</td></tr><tr><td><code>run/backend.ts</code></td><td>后端调度 — 委托给 LLM SDK</td></tr><tr><td><code>model-fallback.ts</code></td><td>模型故障转移 — 失败时切换提供商/模型</td></tr><tr><td><code>tool-loop-detection.ts</code></td><td>工具循环检测 — 防止无限循环</td></tr></tbody></table><p>核心原理：Agent 在 <code>while(true)</code> 循环中运行，每次循环 = 一次&quot;尝试&quot;：构建 prompt → 调用 LLM → LLM 内部工具循环 → 返回 → 压缩上下文 → 检查溢出/失败 → 重试或结束。</p><h3 id="_2-auto-reply-回复管道-src-auto-reply" tabindex="-1">2. Auto-Reply 回复管道（<code>src/auto-reply/</code>） <a class="header-anchor" href="#_2-auto-reply-回复管道-src-auto-reply" aria-label="Permalink to “2. Auto-Reply 回复管道（src/auto-reply/）”">​</a></h3><p>消息从渠道进来到回复出去的全链路：Dispatch → Context Prep → Command Routing → Reply Dispatcher → Pre-flight Compaction。</p><h2 id="第二梯队-插件与扩展体系" tabindex="-1">第二梯队：插件与扩展体系 <a class="header-anchor" href="#第二梯队-插件与扩展体系" aria-label="Permalink to “第二梯队：插件与扩展体系”">​</a></h2><h3 id="_3-plugin-sdk-src-plugin-sdk" tabindex="-1">3. Plugin SDK（<code>src/plugin-sdk/</code>） <a class="header-anchor" href="#_3-plugin-sdk-src-plugin-sdk" aria-label="Permalink to “3. Plugin SDK（src/plugin-sdk/）”">​</a></h3><p>扩展 OpenClaw 的唯一官方入口。三种插件类型：</p><table tabindex="0"><thead><tr><th>类型</th><th>目录</th><th>职责</th></tr></thead><tbody><tr><td>Channel</td><td><code>extensions/*/</code></td><td>接入消息渠道（Telegram、微信、Discord…）</td></tr><tr><td>Provider</td><td><code>extensions/*/</code></td><td>接入 AI 模型（OpenAI、Claude、Gemini…）</td></tr><tr><td>Tool</td><td><code>extensions/*/</code></td><td>扩展工具能力（搜索、浏览器、代码执行…）</td></tr></tbody></table><p>关键 SDK 文件：<code>src/plugin-sdk/api.ts</code>（公开类型和接口）、<code>src/plugin-sdk/runtime-api.ts</code>（插件运行时获取的助手函数）。</p><h3 id="_4-plugin-loader-src-plugins" tabindex="-1">4. Plugin Loader（<code>src/plugins/</code>） <a class="header-anchor" href="#_4-plugin-loader-src-plugins" aria-label="Permalink to “4. Plugin Loader（src/plugins/）”">​</a></h3><p>插件如何被发现、加载、注册、生命周期管理。核心概念：Manifest（<code>openclaw.plugin.json</code>）、Registration、Lifecycle。</p><h2 id="第三梯队-gateway-与基础设施" tabindex="-1">第三梯队：Gateway 与基础设施 <a class="header-anchor" href="#第三梯队-gateway-与基础设施" aria-label="Permalink to “第三梯队：Gateway 与基础设施”">​</a></h2><h3 id="_5-gateway-控制平面-src-gateway" tabindex="-1">5. Gateway 控制平面（<code>src/gateway/</code>） <a class="header-anchor" href="#_5-gateway-控制平面-src-gateway" aria-label="Permalink to “5. Gateway 控制平面（src/gateway/）”">​</a></h3><p>系统的总线和调度中心：HTTP/WS Server、Auth、Config Hot Reload、Plugin Manager、Cron、Channel Manager。</p><h3 id="_6-配置系统-src-config" tabindex="-1">6. 配置系统（<code>src/config/</code>） <a class="header-anchor" href="#_6-配置系统-src-config" aria-label="Permalink to “6. 配置系统（src/config/）”">​</a></h3><p>300+ 配置项，<code>openclaw.json</code> 主配置文件，配置引擎加载/验证/合并默认值，<code>openclaw doctor --fix</code> 配置迁移机制。</p><h3 id="_7-上下文引擎-src-context-engine" tabindex="-1">7. 上下文引擎（<code>src/context-engine/</code>） <a class="header-anchor" href="#_7-上下文引擎-src-context-engine" aria-label="Permalink to “7. 上下文引擎（src/context-engine/）”">​</a></h3><p>管理 Agent 上下文窗口：Compaction（自动压缩）、Token Budget（按模型分配）、Truncation Strategy（截断策略）。</p><h2 id="第四梯队-进阶扩展能力" tabindex="-1">第四梯队：进阶扩展能力 <a class="header-anchor" href="#第四梯队-进阶扩展能力" aria-label="Permalink to “第四梯队：进阶扩展能力”">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>说明</th></tr></thead><tbody><tr><td>记忆系统（<code>src/memory/</code>）</td><td>ActiveMemory / Wiki / Vector 三种模式，SQLite 统一存储</td></tr><tr><td>MCP（<code>src/mcp/</code>）</td><td>Model Context Protocol，让外部工具接入 Agent</td></tr><tr><td>Skills（<code>src/skills/</code>）</td><td>可安装的技能包系统</td></tr><tr><td>Hooks（<code>src/hooks/</code>）</td><td>生命周期钩子：<code>before_agent_start</code>、<code>after_agent_finalize</code> 等</td></tr></tbody></table><h2 id="_4-周学习路线图" tabindex="-1">4 周学习路线图 <a class="header-anchor" href="#_4-周学习路线图" aria-label="Permalink to “4 周学习路线图”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>第1周：运行起来</span></span>
<span class="line"><span>├── pnpm install &amp;&amp; pnpm gateway:watch</span></span>
<span class="line"><span>├── 配置一个最简单的 agent + 一个 channel</span></span>
<span class="line"><span>└── 体验一条消息从发送到回复的完整流程</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第2周：理解 Agent 引擎</span></span>
<span class="line"><span>├── 读 src/agents/embedded-agent-runner/run.ts</span></span>
<span class="line"><span>├── 跟踪一次 while(true) 循环的全过程</span></span>
<span class="line"><span>├── 理解工具调用、压缩、重试的触发条件</span></span>
<span class="line"><span>└── 看 test/agents/ 中的测试用例</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第3周：掌握插件体系</span></span>
<span class="line"><span>├── 读 src/plugin-sdk/api.ts</span></span>
<span class="line"><span>├── 仿写一个最简单的 channel 插件</span></span>
<span class="line"><span>├── 理解 manifest 和注册流程</span></span>
<span class="line"><span>└── 读一个官方插件源码（如 extensions/telegram）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第4周：深入基础设施</span></span>
<span class="line"><span>├── 配置引擎和热重载</span></span>
<span class="line"><span>├── 上下文管理和压缩策略</span></span>
<span class="line"><span>├── 记忆系统和 SQLite 存储</span></span>
<span class="line"><span>└── Hooks 和 MCP 集成</span></span></code></pre></div><h2 id="关键文件速查" tabindex="-1">关键文件速查 <a class="header-anchor" href="#关键文件速查" aria-label="Permalink to “关键文件速查”">​</a></h2><table tabindex="0"><thead><tr><th>想看什么</th><th>读什么</th></tr></thead><tbody><tr><td>Agent 怎么跑起来的</td><td><code>src/agents/embedded-agent-runner/run.ts</code></td></tr><tr><td>消息怎么处理的</td><td><code>src/auto-reply/</code></td></tr><tr><td>怎么写插件</td><td><code>src/plugin-sdk/api.ts</code></td></tr><tr><td>怎么接新渠道</td><td><code>extensions/telegram/src/index.ts</code> 参考</td></tr><tr><td>配置怎么加载</td><td><code>src/config/</code></td></tr><tr><td>上下文怎么压缩</td><td><code>src/context-engine/</code></td></tr><tr><td>测试怎么写</td><td><code>test/</code> 目录下对应模块</td></tr></tbody></table><blockquote><p>想用 OpenClaw → 学配置；想扩展 OpenClaw → 学 Plugin SDK；想理解 OpenClaw 原理 → 学 Agent 执行引擎的 <code>while(true)</code> 主循环。</p></blockquote>`,30)),t(n),t(s)])}const k=d(c,[["render",p]]);export{w as __pageData,k as default};
